      "label": "met",
      "reason": "Alle tre kritiske elementer nævnes: journaler fra egen læge, speciallæge, hospital eller ambulant klinik, beskrivelse af den varige funktionsnedsættelse, og epikrise eller afslutningsbrev ved afsluttet behandling. Forbeholdet 'som udgangspunkt' mangler, men det behandles under C08 og C10."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret angiver direkte, hvilken lægelig dokumentation en ansøgning skal indeholde, når behandlingen er afsluttet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret henviser ikke til nogen identificerbar kilde som bestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer et ubetinget krav om epikrise eller afslutningsbrev som minimumsindhold. Vejledningen understøtter kun, at dokumentationen som udgangspunkt vil indeholde det."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdet 'som udgangspunkt' ved epikrise eller afslutningsbrev er udeladt. Svaret nævner heller ikke, at dokumentets betegnelse ikke i sig selv afgør tilstrækkeligheden."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en kort, intern konsistent opregning, og følgesætningen om afvisning er sammenhængende med resten. Der er ingen modstrid mellem trinene."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Skal som minimum indeholde' gælder også epikrisen, så en vejledende udgangspunktsregel bliver til et absolut krav. Afvisningsfølgen gengives som 'kan afvise', mens kilden siger 'afviser'. Det er en mindre afvigelse, men hovedfejlen er den absolutte formulering."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "partial",
      "reason": "Svaret nævner, at epikrise eller afslutningsbrev hører med ved afsluttet behandling. Det gengiver ikke 'som udgangspunkt' og gør det til et absolut krav."
    },
    "A32": {
      "label": "partial",
      "reason": "Svaret dækker, at dokumentationen indeholder epikrise eller afslutningsbrev. Det mangler forbeholdet 'som udgangspunkt' og angiver det i stedet som obligatorisk."
    }
  },
  "overall_notes": "Indholdet svarer i store træk til vejledningen: journaler, beskrivelse af den varige funktionsnedsættelse og epikrise eller afslutningsbrev. Den væsentlige fejl er, at epikrise eller afslutningsbrev præsenteres som et ufravigeligt minimumskrav i stedet for noget, der som udgangspunkt indgår. Svaret angiver ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable."
}

